const docs = $input.all();
const chunks = docs.map(d => {
  const j = d.json || {};
  return (j.document && j.document.pageContent) || j.pageContent || j.text || '';
}).filter(Boolean);
const context = chunks.length
  ? chunks.map((c, i) => `[Chunk ${i + 1}]\n${c}`).join('\n\n---\n\n')
  : '(no relevant knowledge base entries found)';
const body = ($('Webhook').first().json.body) || {};
const message = body.message || '';
const history = Array.isArray(body.history) ? body.history : [];
const historyText = history.map(h => `${h.role}: ${h.content}`).join('\n') || '(none)';
return [{ json: { context, message, historyText } }];
